return items.map((item) => {
  const json = item.json;

  const rawTitle = json.title || '';
  const rawDescription = json.content || json.description_text || json.description || '';

  const title = normalizeText(rawTitle);
  const description = normalizeText(rawDescription);

  const directTitleMatches = findMatches(title, directTitlePhrases);
  const ambiguousTitleMatches = findMatches(title, ambiguousTitlePhrases);
  const negativeTitleMatches = findMatches(title, negativeTitlePhrases);
  const descriptionMatches = findMatches(description, descriptionSupportPhrases);

  const isRelevant =
    negativeTitleMatches.length === 0 &&
    (
      directTitleMatches.length > 0 ||
      (ambiguousTitleMatches.length > 0 && descriptionMatches.length > 0)
    );

  json.description_text = cleanHtml(rawDescription);
  json.isRelevant = isRelevant;
  json.matchReason = {
    directTitleMatches,
    ambiguousTitleMatches,
    negativeTitleMatches,
    descriptionMatches,
    isRelevant
  };

  return item;
});
